insert into public.events (id, title, date, time, location, description, category, layout, format, platform, participants, speakers, key_points, winners, sessions, competition_sections, links, image, image_alt, logo, brochure, additional_info) values ('dissertation-project-work-2025', 'Dissertation and Academic Project Work', '2025-09-24', '12:30 PM', 'Keshav Mahavidyalaya, Computer Science Department', 'Seminar and orientation session covering research problems, literature review, research design, methodology, lab assessment guidelines, and academic integrity.', 'Seminar / Orientation', 'workshop', 'Seminar / Orientation', NULL, NULL, array['Prof. Preeti Sehgal', 'Dr. Ashutosh Singh', 'Prof. Vinita Jindal']::text[], array['Research problems and literature review', 'Research design and methodology', 'Assessment guidelines and academic integrity']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, 'Speakers: Prof. Preeti Sehgal, Dr. Ashutosh Singh and Prof. Vinita Jindal. Time: 12:30 PM.') on conflict (id) do nothing;
insert into public.events (id, title, date, time, location, description, category, layout, format, platform, participants, speakers, key_points, winners, sessions, competition_sections, links, image, image_alt, logo, brochure, additional_info) values ('uiux-design-workshop-2025', 'UI/UX Design Workshop', '2025-11-01', '11:00 AM', 'Online', 'An online workshop focused on design thinking, problem identification, the Double Diamond process, wireframing, and prototyping.', 'Workshop', 'workshop', 'Online', NULL, NULL, array['Anjali']::text[], array['Design thinking and problem identification', 'Double Diamond process', 'Wireframing and prototyping']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, 'Time: 11:00 AM.') on conflict (id) do nothing;
insert into public.events (id, title, date, time, location, description, category, layout, format, platform, participants, speakers, key_points, winners, sessions, competition_sections, links, image, image_alt, logo, brochure, additional_info) values ('code-verse-2026', 'Code Verse — Coding Competition', '2026-01-16', '11:00 AM–12:30 PM', 'Lab 1', 'Six coding questions across easy, medium, and hard categories on HackerRank, with nine teams participating.', 'Coding Competition', 'competition', 'Hackerrank Competition', 'HackerRank', 'Nine teams', '{}'::text[], array['Six coding questions', 'Easy, medium and hard categories', 'Nine teams participated']::text[], '[{"position":"First","names":["Vishal","Daksh Sahni"]},{"position":"Second","names":["Mayank Kansal","Aniket Jaiswal"]},{"position":"Third","names":["Tarun Jaiswal","Krish Kumar Jaiswal"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, 'assets/images/collaborations/partner-hack.svg', NULL, 'Winners: 1st Vishal and Daksh Sahni; 2nd Mayank Kansal and Aniket Jaiswal; 3rd Tarun Jaiswal and Krish Kumar Jaiswal. Time: 11:00 AM–12:30 PM.') on conflict (id) do nothing;
insert into public.events (id, title, date, time, location, description, category, layout, format, platform, participants, speakers, key_points, winners, sessions, competition_sections, links, image, image_alt, logo, brochure, additional_info) values ('technyx-2026', 'TECHNYX 2026', '2026-01-27', NULL, 'Keshav Mahavidyalaya', 'A parent technical event combining multiple student-facing sessions on internships, Git and GitHub, web fundamentals, and NLP.', 'Technical Event', 'festival', 'Parent Event', NULL, NULL, '{}'::text[], '{}'::text[], '[]'::jsonb, '[{"id":"internships-what-companies-expect","title":"Internships — What Companies Expect","date":"2026-01-27","speakers":["Soumya Ranjan","Riya Arora"],"summary":"Session on internship expectations, technical and soft skills, communication, work ethics and professionalism."},{"id":"git-github-bootcamp","title":"Git and GitHub — Bootcamp","date":"2026-01-29","speakers":["Natya Vidhan Biswas","Parth Arora"],"summary":"Session on version control, repositories, commits and collaboration workflows."},{"id":"from-url-to-webpage","title":"From URL to Webpage — Understanding the Web","date":"2026-02-01","speakers":["Aksh Kumar","Ayushi Jain"],"summary":"Session on URLs, DNS, servers, HTTP/HTTPS, web development, APIs and databases."},{"id":"natural-language-processing","title":"Natural Language Processing","date":"2026-02-02","speakers":["Vrinda Goyal","Priyal Vatsa"],"summary":"Session on AI, NLP fundamentals, tokenization, stop-word removal, stemming, lemmatization and text mining."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, 'Sessions included: Internships — What Companies Expect (27 Jan); Git and GitHub Bootcamp (29 Jan); From URL to Webpage — Understanding the Web (1 Feb); Natural Language Processing (2 Feb).') on conflict (id) do nothing;
insert into public.events (id, title, date, time, location, description, category, layout, format, platform, participants, speakers, key_points, winners, sessions, competition_sections, links, image, image_alt, logo, brochure, additional_info) values ('agentic-ai-speaker-session-2026', 'Agentic AI Speaker Session', NULL, NULL, 'Keshav Mahavidyalaya', 'Speaker session on AI agents, multi-agent systems, API-based agents, applications, limitations, and responsible implementation.', 'Speaker Session', 'speaker', 'Speaker Session', NULL, NULL, array['Dr. Manish Gupta']::text[], array['AI agents and multi-agent systems', 'Practical demonstrations', 'API-based agents, applications and limitations', 'Responsible implementation']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, 'Speaker: Dr. Manish Gupta.') on conflict (id) do nothing;
insert into public.events (id, title, date, time, location, description, category, layout, format, platform, participants, speakers, key_points, winners, sessions, competition_sections, links, image, image_alt, logo, brochure, additional_info) values ('blitzkrieg-2026', 'BLITZKRIEG 2026', '2026-03-12', NULL, 'Keshav Mahavidyalaya Campus', 'The annual technical fest featuring a speaker session on cloud computing, SaaS, PaaS, IaaS, and career opportunities, alongside student competitions and interactive events.', 'Annual Technical Fest', 'festival', 'Annual Technical Fest', NULL, NULL, array['Prof. Rahul Johari']::text[], '{}'::text[], '[]'::jsonb, '[]'::jsonb, '[{"title":"Eleven’s Logic Lab","type":"Quiz"},{"title":"Between the 2 Worlds","type":"Debate"},{"title":"Upside Showdown","type":"BGMI Tournament"},{"title":"Hawkings Hack","type":"Hackathon"},{"title":"Escape the Upside Down","type":"Treasure Hunt"}]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, 'Featured sub-events: Eleven’s Logic Lab — Quiz; Between the 2 Worlds — Debate; Upside Showdown — BGMI Tournament; Hawkings Hack — Hackathon; Escape the Upside Down — Treasure Hunt.') on conflict (id) do nothing;
